INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5242, 1, 127, 183, '168-L009-CB-MC -BLK', '168 L009 Cable (Micro USB / Black)', '168-l009-cable-micro-usb-black-fsey0', '<p><strong>L009 Cable</strong></p><p>L009 Cable သည် <strong>168</strong> အမှတ်တံဆိပ် Cable အမျိုးအစား (Cable &amp; Charger) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ကြာရှည်ခံပြီး အားသွင်းမှု မြန်ဆန်သော အရည်အသွေးကောင်း ကြိုးဖြစ်ပါသည်။ နေ့စဉ်အသုံးပြုမှုအတွက် ခိုင်ခံ့ပြီး ယုံကြည်စိတ်ချရပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Micro USB / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> 168-L009-CB-MC -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> 168</li><li><strong>အမျိုးအစား (Category):</strong> Cable</li><li><strong>Parent Category:</strong> Cable &amp; Charger</li><li><strong>မျိုးကွဲ (Variant):</strong> Micro USB / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', '168 L009 Cable (Micro USB / Black) — Cable အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '4500.00', '4000.00', NULL, NULL, '3500.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:07', '2026-08-16 11:19:27');
