INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5248, 1, 130, 187, 'ANT-400-CHS-MC', 'Antclan 400 Charger Set (Micro USB)', 'antclan-400-charger-set-micro-usb-y4iih', '<p><strong>400 Charger Set</strong></p><p>400 Charger Set သည် <strong>Antclan</strong> အမှတ်တံဆိပ် Charger Set အမျိုးအစား (Cable &amp; Charger) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>အားသွင်းကြိုးနှင့် အဒက်တာ အပြည့်အစုံပါဝင်သော အားသွင်းကိရိယာ အစုံဖြစ်ပြီး မြန်ဆန်လုံခြုံစွာ အားသွင်းနိုင်ပါသည်။ အိမ်၊ ရုံးနှင့် ခရီးသွားချိန်များတွင် အသုံးပြုရန် အဆင်ပြေပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Micro USB။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> ANT-400-CHS-MC</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Antclan</li><li><strong>အမျိုးအစား (Category):</strong> Charger Set</li><li><strong>Parent Category:</strong> Cable &amp; Charger</li><li><strong>မျိုးကွဲ (Variant):</strong> Micro USB — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Antclan 400 Charger Set (Micro USB) — Charger Set အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '14000.00', '12600.00', NULL, NULL, '13000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:07', '2026-08-13 14:21:07');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5249, 1, 132, 188, 'BL-4C-BT', 'Nokia 4C Battery', 'nokia-4c-battery-xhi2d', '<p><strong>4C Battery</strong></p><p>4C Battery သည် <strong>Nokia</strong> အမှတ်တံဆိပ် Standard Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>အရည်အသွေးမြင့် Standard ဘက်ထရီဖြစ်ပြီး တာရှည်အသုံးပြုနိုင်မှုနှင့် တည်ငြိမ်သော အားပြန်ထုတ်မှုကို ပေးစွမ်းပါသည်။ ဘက်ထရီ အစားထိုးလိုသူများအတွက် လက်တွေ့ကျပြီး တန်ဖိုးရှိသော ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> BL-4C-BT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Nokia</li><li><strong>အမျိုးအစား (Category):</strong> Standard Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Nokia 4C Battery — Standard Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '7795.00', '7016.00', NULL, NULL, '7456.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:07', '2026-08-13 14:21:07');
