INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5347, 1, 132, 201, 'HW-NOVA5-BT-WHT', 'Huawei Nova 5 Battery (White)', 'huawei-nova-5-battery-white-anadg', '<p><strong>Nova 5 Battery</strong></p><p>Nova 5 Battery သည် <strong>Huawei</strong> အမှတ်တံဆိပ် Standard Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>အရည်အသွေးမြင့် Standard ဘက်ထရီဖြစ်ပြီး တာရှည်အသုံးပြုနိုင်မှုနှင့် တည်ငြိမ်သော အားပြန်ထုတ်မှုကို ပေးစွမ်းပါသည်။ ဘက်ထရီ အစားထိုးလိုသူများအတွက် လက်တွေ့ကျပြီး တန်ဖိုးရှိသော ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): White။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> HW-NOVA5-BT-WHT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Huawei</li><li><strong>အမျိုးအစား (Category):</strong> Standard Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>မျိုးကွဲ (Variant):</strong> White — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Huawei Nova 5 Battery (White) — Standard Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '23000.00', '20700.00', NULL, NULL, '22000.00', 'in_stock', 'products/uTE48E9Tjro5HB5rWg2MZcO0ddQp0GcLUgn5YHDq.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-22 16:46:32');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5348, 1, 147, 201, 'HW-NOVA5I-GLS-OCA -BLK', 'Huawei Nova 5i / Nova 7i / P40 Lite OCA Glass', 'huawei-nova-5i-nova-7i-p40-lite-oca-glass-f40p2', '<p><strong>Nova 5i / Nova 7i/P40 Lite OCA Glass</strong></p><p>Nova 5i / Nova 7i/P40 Lite OCA Glass သည် <strong>Huawei</strong> အမှတ်တံဆိပ် OCA Glass အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>OCA Glass ဖန်မျက်နှာပြင်ဖြစ်ပြီး မူရင်းပုံစံအတိုင်း ပြတ်သားမှုနှင့် ထိခိုက်မှုဒဏ်ကို ခံနိုင်စွမ်းကောင်းမွန်ပါသည်။ မျက်နှာပြင် ပြုပြင်ရာတွင် အသုံးပြုနိုင်သော အရည်အသွေးကောင်း အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): OCA / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> HW-NOVA5I-GLS-OCA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Huawei</li><li><strong>အမျိုးအစား (Category):</strong> OCA Glass</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> OCA / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Huawei Nova 5i / Nova 7i/P40 Lite OCA Glass — OCA Glass ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '13000.00', '11700.00', NULL, NULL, '12000.00', 'in_stock', 'products/rZmtFcPh2FD3nDBSqEkvWrkthUel0e06O5jzrX9J.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 1, '2026-08-13 14:21:08', '2026-08-29 10:13:35');
