INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5350, 1, 146, 201, 'HW-NOVA8I-TL-ORG -BLK', 'Huawei Nova 8i / Nova 9Z Touch LCD', 'huawei-nova-8i-nova-9z-touch-lcd-odtqg', '<p><strong>Nova 8i / Nova 9Z Touch LCD</strong></p><p>Nova 8i / Nova 9Z Touch LCD သည် <strong>Huawei</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> HW-NOVA8I-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Huawei</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Huawei Nova 8i / Nova 9Z Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '46000.00', '41400.00', NULL, NULL, '44000.00', 'in_stock', 'products/K04GtK4xKd6rQMgCQ5m58xgvSdxzQ8AX0J3Msagt.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-13 19:47:39');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5352, 1, 149, 201, 'HW-Nova3i-BC-BLK', 'Huawei Nova 3i Back Cover (Black, Blue)', 'huawei-nova-3i-back-cover-black-blue-oy1uw', '<p><strong>Nova 3i Back Cover</strong></p><p>Nova 3i Back Cover သည် <strong>Huawei</strong> အမှတ်တံဆိပ် Back Cover အမျိုးအစား (Body &amp; Back Cover) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်း၏ နောက်ကျောဘက်ကို ကာကွယ်ပေးနိုင်သော Back Cover ဖြစ်ပြီး ခိုင်ခံ့သော ပစ္စည်းဖြင့် ပြုလုပ်ထားပါသည်။ ဖုန်း၏ အသွင်အပြင်ကို မြှင့်တင်ပေးပြီး ထိခိုက်မှုမှလည်း ကာကွယ်ပေးပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): Black, Blue (SKU: HW-Nova3i-BC-BLK, HW-Nova3i-BC-BLU)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> HW-Nova3i-BC-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Huawei</li><li><strong>အမျိုးအစား (Category):</strong> Back Cover</li><li><strong>Parent Category:</strong> Body &amp; Back Cover</li><li><strong>မျိုးကွဲများ (Variants):</strong> Black (HW-Nova3i-BC-BLK) — စတော့ရှိသည် (In Stock)၊ Blue (HW-Nova3i-BC-BLU) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Huawei Nova 3i Back Cover (Black, Blue) — Back Cover အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '12000.00', '10800.00', NULL, NULL, '11000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-15 10:40:45');
