INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5459, 1, 132, 208, 'IT-BL25-BT', 'itel BL25 Battery', 'itel-bl25-battery-nmyyh', '<p><strong>BL25 Battery</strong></p><p>BL25 Battery သည် <strong>itel</strong> အမှတ်တံဆိပ် Standard Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>အရည်အသွေးမြင့် Standard ဘက်ထရီဖြစ်ပြီး တာရှည်အသုံးပြုနိုင်မှုနှင့် တည်ငြိမ်သော အားပြန်ထုတ်မှုကို ပေးစွမ်းပါသည်။ ဘက်ထရီ အစားထိုးလိုသူများအတွက် လက်တွေ့ကျပြီး တန်ဖိုးရှိသော ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> IT-BL25-BT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> itel</li><li><strong>အမျိုးအစား (Category):</strong> Standard Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'itel BL25 Battery — Standard Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '6900.00', '6210.00', NULL, NULL, '6600.00', 'out_of_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-15 13:31:40');
