INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5517, 1, 146, 216, 'OP-A3S-TL-ORG -BLK', 'OPPO A3S / OPA5 / REALME C1 Touch LCD', 'oppo-a3s-opa5-realme-c1-touch-lcd-ayi5a', '<p><strong>A3S / OPA5/REALME C1 Touch LCD</strong></p><p>A3S / OPA5/REALME C1 Touch LCD သည် <strong>OPPO</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> OP-A3S-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> OPPO</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'OPPO A3S / OPA5/REALME C1 Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '37000.00', '33300.00', NULL, NULL, '36000.00', 'in_stock', 'products/6NwYWVv42H6S54q7Kil2McbPy0n2OGc6jHtYZWCK.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-17 14:57:26');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5518, 1, 150, 216, 'OP-A5/2020-CV', 'OPPO A5 / 2020 Cover', 'oppo-a5-2020-cover-cwhh2', '<p><strong>A5/2020 Phone Case</strong></p><p>A5/2020 Phone Case သည် <strong>OPPO</strong> အမှတ်တံဆိပ် Phone Case အမျိုးအစား (Phone Accessories) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်းကို ထိခိုက်ပျက်စီးမှုနှင့် ခြစ်ရာများမှ ကာကွယ်ပေးနိုင်သော အရည်အသွေးကောင်း ဖုန်းကာဗာဖြစ်ပါသည်။ လက်ကိုင်အနေအထား သက်တောင့်သက်သာရှိပြီး စတိုင်ကျသော အသွင်အပြင်ကိုလည်း ပေးစွမ်းပါသည်။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> OP-A5/2020-CV</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> OPPO</li><li><strong>အမျိုးအစား (Category):</strong> Phone Case</li><li><strong>Parent Category:</strong> Phone Accessories</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'OPPO A5/2020 Phone Case — Phone Case အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '7000.00', '6500.00', NULL, NULL, '6000.00', 'out_of_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-17 15:22:49');
