INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5540, 1, 146, 216, 'OP-A83-TL-WHT', 'OPPO A83 / F5 Lite Touch LCD (White)', 'oppo-a83-f5-lite-touch-lcd-white-cy3yk', '<p><strong>A83 / OPPO F5 Lite Touch LCD</strong></p><p>A83 / OPPO F5 Lite Touch LCD သည် <strong>OPPO</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): White။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> OP-A83-TL-WHT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> OPPO</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> White — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'OPPO A83 / OPPO F5 Lite Touch LCD (White) — Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '37500.00', '33750.00', NULL, NULL, '37000.00', 'in_stock', 'products/QS8SZBlJln4CWjEzTWKnQnRVwRbgnT5R4NTqFzgf.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-17 15:12:29');
