INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5652, 1, 146, 217, 'RM-10(5G)-TL-BLK', 'Redmi 10 5G Touch LCD (Black)', 'redmi-10-5g-touch-lcd-black-brizo', '<p><strong>10 5G Touch LCD</strong></p><p>10 5G Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-10(5G)-TL-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 10 5G Touch LCD (Black) — Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '42000.00', '37800.00', NULL, NULL, '41000.00', 'in_stock', 'products/ksZ6NUeC2Kng0FVwasSBdBqKFwjuRyJvGWs9qdnT.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-16 15:12:20');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5653, 1, 146, 217, 'RM-104G-TL-ORG -BLK', 'Redmi 104G Touch LCD (Original / Black)', 'redmi-104g-touch-lcd-original-black-bwb83', '<p><strong>104G Touch LCD</strong></p><p>104G Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-104G-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 104G Touch LCD (Original / Black) — Original Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '38000.00', '34200.00', NULL, NULL, '38000.00', 'in_stock', 'products/23FrFIw8iszuHqT59DRLAyeTtrgLKM1xNl08S6YO.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-13 19:16:30');
