INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5658, 1, 147, 217, 'RM-10X-GLS-OCA -BLK', 'Redmi 10X OCA Glass (OCA / Black)', 'redmi-10x-oca-glass-oca-black-qbufd', '<p><strong>10X OCA Glass</strong></p><p>10X OCA Glass သည် <strong>Redmi</strong> အမှတ်တံဆိပ် OCA Glass အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>OCA Glass ဖန်မျက်နှာပြင်ဖြစ်ပြီး မူရင်းပုံစံအတိုင်း ပြတ်သားမှုနှင့် ထိခိုက်မှုဒဏ်ကို ခံနိုင်စွမ်းကောင်းမွန်ပါသည်။ မျက်နှာပြင် ပြုပြင်ရာတွင် အသုံးပြုနိုင်သော အရည်အသွေးကောင်း အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): OCA / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-10X-GLS-OCA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> OCA Glass</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> OCA / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 10X OCA Glass (OCA / Black) — OCA Glass အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '9000.00', '8100.00', NULL, NULL, '8000.00', 'in_stock', 'products/dvFe6NxqzR2Il2D8SmddKqRvMKgFilQrw3dr5D6v.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-27 13:48:53');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5659, 1, 132, 217, 'RM-10x5G(BM4S)-BT-ORG', 'Redmi 10X5G(BM4S) Battery (Original)', 'redmi-10x5gbm4s-battery-original-vcqk4', '<p><strong>10X5G(BM4S) Battery</strong></p><p>10X5G(BM4S) Battery သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) အရည်အသွေးရှိသော ဘက်ထရီဖြစ်ပြီး ဖုန်း၏ စွမ်းဆောင်ရည်ကို အပြည့်အဝ ပြန်လည်ရရှိစေပါသည်။ ကြာရှည်ခံပြီး လုံခြုံစိတ်ချရသော အသုံးပြုမှုအတွက် သင့်လျော်သော ရွေးချယ်မှုတစ်ခု ဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-10x5G(BM4S)-BT-ORG</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>မျိုးကွဲ (Variant):</strong> Original — ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 10X5G(BM4S) Battery (Original) — Original Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '23000.00', '20700.00', NULL, NULL, '22000.00', 'out_of_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-14 13:08:49');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5660, 1, 146, 217, 'RM-11/11S-TL-BLK', 'Redmi N11 / 11s Touch LCD (Black)', 'redmi-n11-11s-touch-lcd-black-a89yh', '<p><strong>N11/11s Touch LCD</strong></p><p>N11/11s Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-11/11S-TL-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi N11/11s Touch LCD (Black) — Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '47000.00', '42300.00', NULL, NULL, '46000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-15 10:01:06');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5661, 1, 149, 217, 'RM-11LITE-BC-BLK', 'Redmi 11 Lite Back Cover (Black, Blue)', 'redmi-11-lite-back-cover-black-blue-7pumw', '<p><strong>11 Lite Back Cover</strong></p><p>11 Lite Back Cover သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Back Cover အမျိုးအစား (Body &amp; Back Cover) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်း၏ နောက်ကျောဘက်ကို ကာကွယ်ပေးနိုင်သော Back Cover ဖြစ်ပြီး ခိုင်ခံ့သော ပစ္စည်းဖြင့် ပြုလုပ်ထားပါသည်။ ဖုန်း၏ အသွင်အပြင်ကို မြှင့်တင်ပေးပြီး ထိခိုက်မှုမှလည်း ကာကွယ်ပေးပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): Black, Blue (SKU: RM-11LITE-BC-BLK, RM-11LITE-BC-BLU)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-11LITE-BC-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Back Cover</li><li><strong>Parent Category:</strong> Body &amp; Back Cover</li><li><strong>မျိုးကွဲများ (Variants):</strong> Black (RM-11LITE-BC-BLK) — စတော့ရှိသည် (In Stock)၊ Blue (RM-11LITE-BC-BLU) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 11 Lite Back Cover (Black, Blue) — Back Cover အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '13000.00', '11700.00', NULL, NULL, '12000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-15 13:14:46');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5662, 1, 150, 217, 'RM-11T-CV', 'Redmi 11T Cover', 'redmi-11t-cover-jrlqy', '<p><strong>11T Phone Case</strong></p><p>11T Phone Case သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Phone Case အမျိုးအစား (Phone Accessories) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်းကို ထိခိုက်ပျက်စီးမှုနှင့် ခြစ်ရာများမှ ကာကွယ်ပေးနိုင်သော အရည်အသွေးကောင်း ဖုန်းကာဗာဖြစ်ပါသည်။ လက်ကိုင်အနေအထား သက်တောင့်သက်သာရှိပြီး စတိုင်ကျသော အသွင်အပြင်ကိုလည်း ပေးစွမ်းပါသည်။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-11T-CV</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Phone Case</li><li><strong>Parent Category:</strong> Phone Accessories</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 11T Phone Case — Phone Case အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '7000.00', '6500.00', NULL, NULL, '6000.00', 'out_of_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:08', '2026-08-17 14:56:40');
