INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5698, 1, 161, 217, 'RM-5A-TS-AAA -BLK', 'Redmi 5A Touch Screen', 'redmi-5a-touch-screen-dbi8a', '<p><strong>5A Touch Screen</strong></p><p>5A Touch Screen သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch Screen အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch Screen အစိတ်အပိုင်းဖြစ်ပြီး မြန်ဆန်တိကျသော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ မျက်နှာပြင် ထိန်းချုပ်မှု ပြဿနာများအတွက် သင့်လျော်သော အစားထိုး အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): AAA / Black, AAA / White (SKU: RM-5A-TS-AAA -BLK, RM-5A-TS-AAA -WHT)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-5A-TS-AAA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch Screen</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲများ (Variants):</strong> AAA / Black (RM-5A-TS-AAA -BLK) — စတော့ရှိသည် (In Stock)၊ AAA / White (RM-5A-TS-AAA -WHT) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 5A Touch Screen — Touch Screen ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '6000.00', '5400.00', NULL, NULL, '5000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-15 11:58:16');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5699, 1, 147, 217, 'RM-5PLUS-GLS-AAA -BLK', 'Redmi 5 Plus Front Glass', 'redmi-5-plus-front-glass-jp5wv', '<p><strong>5 Plus Front Glass</strong></p><p>5 Plus Front Glass သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch Screen အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch Screen အစိတ်အပိုင်းဖြစ်ပြီး မြန်ဆန်တိကျသော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ မျက်နှာပြင် ထိန်းချုပ်မှု ပြဿနာများအတွက် သင့်လျော်သော အစားထိုး အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): AAA / Black, AAA / White (SKU: RM-5PLUS-GLS-AAA -BLK, RM-5PLUS-GLS-AAA -WHT)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-5PLUS-GLS-AAA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch Screen</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲများ (Variants):</strong> AAA / Black (RM-5PLUS-GLS-AAA -BLK) — စတော့ရှိသည် (In Stock)၊ AAA / White (RM-5PLUS-GLS-AAA -WHT) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 5 Plus Front Glass — Touch Screen ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '5750.00', '5175.00', NULL, NULL, '5500.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-15 11:58:41');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5700, 1, 146, 217, 'RM-5X-TL-ORG -WHT', 'Redmi 5X / MI5X / MIA1 Touch LCD', 'redmi-5x-mi5x-mia1-touch-lcd-5tua4', '<p><strong>5X / MI5X/MIA1 Touch LCD</strong></p><p>5X / MI5X/MIA1 Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / White။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-5X-TL-ORG -WHT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / White — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 5X / MI5X/MIA1 Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '37000.00', '33300.00', NULL, NULL, '36000.00', 'in_stock', 'products/eprTi51Z2Ofo2oIpkUILcD0sBaFO1gQnYNlF67cT.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-14 12:43:20');
