INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5727, 1, 147, 217, 'RM-8-GLS-OCA -BLK', 'Redmi 8 OCA Glass (OCA / Black)', 'redmi-8-oca-glass-oca-black-so9uj', '<p><strong>8 OCA Glass</strong></p><p>8 OCA Glass သည် <strong>Redmi</strong> အမှတ်တံဆိပ် OCA Glass အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>OCA Glass ဖန်မျက်နှာပြင်ဖြစ်ပြီး မူရင်းပုံစံအတိုင်း ပြတ်သားမှုနှင့် ထိခိုက်မှုဒဏ်ကို ခံနိုင်စွမ်းကောင်းမွန်ပါသည်။ မျက်နှာပြင် ပြုပြင်ရာတွင် အသုံးပြုနိုင်သော အရည်အသွေးကောင်း အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): OCA / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-8-GLS-OCA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> OCA Glass</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> OCA / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 8 OCA Glass (OCA / Black) — OCA Glass အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '9000.00', '8100.00', NULL, NULL, '8000.00', 'in_stock', 'products/Dkjt5M7Z93zeA015Aa6fTaIoKgLJLFVeDsVoDlAb.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-27 11:59:57');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5728, 1, 146, 217, 'RM-8-TL-BLK', 'Redmi 8 / 8 / 8A Touch LCD (Black)', 'redmi-8-8-8a-touch-lcd-black-avsuz', '<p><strong>8 / 8/8A Touch LCD</strong></p><p>8 / 8/8A Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-8-TL-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 8 / 8/8A Touch LCD (Black) — Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '38000.00', '34200.00', NULL, NULL, '37000.00', 'in_stock', 'products/yfsiqj1FX9K9bSVaM3cyKElQod3IcAqgDICE0gKf.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-16 13:52:39');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5730, 1, 149, 217, 'RM-8A-BC-BLK', 'Redmi 8A Back Cover (Black, Blue)', 'redmi-8a-back-cover-black-blue-lpsoa', '<p><strong>8A Back Cover</strong></p><p>8A Back Cover သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Back Cover အမျိုးအစား (Body &amp; Back Cover) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်း၏ နောက်ကျောဘက်ကို ကာကွယ်ပေးနိုင်သော Back Cover ဖြစ်ပြီး ခိုင်ခံ့သော ပစ္စည်းဖြင့် ပြုလုပ်ထားပါသည်။ ဖုန်း၏ အသွင်အပြင်ကို မြှင့်တင်ပေးပြီး ထိခိုက်မှုမှလည်း ကာကွယ်ပေးပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): Black, Blue, Red (SKU: RM-8A-BC-BLK, RM-8A-BC-BLU, RM-8A-BC-RED)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-8A-BC-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Back Cover</li><li><strong>Parent Category:</strong> Body &amp; Back Cover</li><li><strong>မျိုးကွဲများ (Variants):</strong> Black (RM-8A-BC-BLK) — စတော့ရှိသည် (In Stock)၊ Blue (RM-8A-BC-BLU) — စတော့ရှိသည် (In Stock)၊ Red (RM-8A-BC-RED) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 8A Back Cover (Black, Blue) — Back Cover အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '9000.00', '8100.00', NULL, NULL, '8000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-16 08:02:40');
