INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5736, 1, 146, 217, 'RM-9/POCOM2-TL-ORG -BLK', 'Redmi 9 / POCOM2 Touch LCD', 'redmi-9-pocom2-touch-lcd-35dor', '<p><strong>9/POCOM2 Touch LCD</strong></p><p>9/POCOM2 Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-9/POCOM2-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 9/POCOM2 Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '38000.00', '34200.00', NULL, NULL, '37000.00', 'in_stock', 'products/USiOD3FCxcriuwrNw9CmQYbrbKVIIwgZuiCxXVGq.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-16 14:34:33');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5737, 1, 130, 217, 'RM-90w-CHS-TC -WHT', 'Redmi 90W Charger Set (Type-C / White)', 'redmi-90w-charger-set-type-c-white-9t5j6', '<p><strong>90W Charger Set</strong></p><p>90W Charger Set သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Charger Set အမျိုးအစား (Cable &amp; Charger) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>အားသွင်းကြိုးနှင့် အဒက်တာ အပြည့်အစုံပါဝင်သော အားသွင်းကိရိယာ အစုံဖြစ်ပြီး မြန်ဆန်လုံခြုံစွာ အားသွင်းနိုင်ပါသည်။ အိမ်၊ ရုံးနှင့် ခရီးသွားချိန်များတွင် အသုံးပြုရန် အဆင်ပြေပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Type-C / White။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-90w-CHS-TC -WHT</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Charger Set</li><li><strong>Parent Category:</strong> Cable &amp; Charger</li><li><strong>မျိုးကွဲ (Variant):</strong> Type-C / White — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 90W Charger Set (Type-C / White) — Charger Set အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '28000.00', '27500.00', NULL, NULL, '27000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-16 13:15:47');
