INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5745, 1, 132, 217, 'RM-9T(BN62)-BT-ORG', 'Redmi 9T(BN62) Battery (Original)', 'redmi-9tbn62-battery-original-hd4vr', '<p><strong>9T(BN62) Battery</strong></p><p>9T(BN62) Battery သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) အရည်အသွေးရှိသော ဘက်ထရီဖြစ်ပြီး ဖုန်း၏ စွမ်းဆောင်ရည်ကို အပြည့်အဝ ပြန်လည်ရရှိစေပါသည်။ ကြာရှည်ခံပြီး လုံခြုံစိတ်ချရသော အသုံးပြုမှုအတွက် သင့်လျော်သော ရွေးချယ်မှုတစ်ခု ဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-9T(BN62)-BT-ORG</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>မျိုးကွဲ (Variant):</strong> Original — ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 9T(BN62) Battery (Original) — Original Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '25000.00', '22500.00', NULL, NULL, '24000.00', 'in_stock', 'products/A7EiXMlkfO3nWmlcZ9bjq2Nd8AFhFyey03ZTR3pA.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-25 14:47:14');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5746, 1, 147, 217, 'RM-9T-GLS-OCA -BLK', 'Redmi 9T OCA Glass (OCA / Black)', 'redmi-9t-oca-glass-oca-black-s7aje', '<p><strong>9T OCA Glass</strong></p><p>9T OCA Glass သည် <strong>Redmi</strong> အမှတ်တံဆိပ် OCA Glass အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>OCA Glass ဖန်မျက်နှာပြင်ဖြစ်ပြီး မူရင်းပုံစံအတိုင်း ပြတ်သားမှုနှင့် ထိခိုက်မှုဒဏ်ကို ခံနိုင်စွမ်းကောင်းမွန်ပါသည်။ မျက်နှာပြင် ပြုပြင်ရာတွင် အသုံးပြုနိုင်သော အရည်အသွေးကောင်း အစိတ်အပိုင်းဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): OCA / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-9T-GLS-OCA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> OCA Glass</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> OCA / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi 9T OCA Glass (OCA / Black) — OCA Glass အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '8050.00', '7245.00', NULL, NULL, '7700.00', 'in_stock', 'products/AGRI9aJrVtgXLDmdjOpSUxPD5BaxCkFLp7BWxkTx.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-27 12:01:26');
