INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5812, 1, 155, 217, 'RM-N10PRO(5G)-BD-BLK', 'Redmi N10 Pro 5G Body Frame (Black, Blue)', 'redmi-n10-pro-5g-body-frame-black-blue-mvkka', '<p><strong>N10 Pro 5G Body Frame</strong></p><p>N10 Pro 5G Body Frame သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Body Frame အမျိုးအစား (Body &amp; Back Cover) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်းကိုယ်ထည် အစိတ်အပိုင်း (Body Frame) ဖြစ်ပြီး ခိုင်ခံ့သော ပစ္စည်းဖြင့် ပြုလုပ်ထားပါသည်။ ဖုန်းကိုယ်ထည် ပျက်စီးမှုကို ပြုပြင်ရာတွင် အသုံးပြုနိုင်ပါသည်။</p><p>ဤပစ္စည်းအတွက် ရနိုင်သော မျိုးကွဲများ (Variants): Black, Blue, Green (SKU: RM-N10PRO(5G)-BD-BLK, RM-N10PRO(5G)-BD-BLU, RM-N10PRO(5G)-BD-GREN)။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-N10PRO(5G)-BD-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Body Frame</li><li><strong>Parent Category:</strong> Body &amp; Back Cover</li><li><strong>မျိုးကွဲများ (Variants):</strong> Black (RM-N10PRO(5G)-BD-BLK) — စတော့ရှိသည် (In Stock)၊ Blue (RM-N10PRO(5G)-BD-BLU) — စတော့ရှိသည် (In Stock)၊ Green (RM-N10PRO(5G)-BD-GREN) — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi N10 Pro 5G Body Frame (Black, Blue) — Body Frame အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '22000.00', '19800.00', NULL, NULL, '21000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 1, '2026-08-13 14:21:09', '2026-08-15 12:56:32');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5813, 1, 132, 217, 'RM-N10PRO(BM57)-BT-ORG', 'Redmi N10 Pro(BM57) Battery (Original)', 'redmi-n10-probm57-battery-original-ts0nb', '<p><strong>N10 Pro(BM57) Battery</strong></p><p>N10 Pro(BM57) Battery သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) အရည်အသွေးရှိသော ဘက်ထရီဖြစ်ပြီး ဖုန်း၏ စွမ်းဆောင်ရည်ကို အပြည့်အဝ ပြန်လည်ရရှိစေပါသည်။ ကြာရှည်ခံပြီး လုံခြုံစိတ်ချရသော အသုံးပြုမှုအတွက် သင့်လျော်သော ရွေးချယ်မှုတစ်ခု ဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-N10PRO(BM57)-BT-ORG</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>မျိုးကွဲ (Variant):</strong> Original — ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi N10 Pro(BM57) Battery (Original) — Original Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '32000.00', '28800.00', NULL, NULL, '31000.00', 'in_stock', 'products/zBLAqKO0ovwE09lz1Srrakh7UMR6NHkyTm0Re6X5.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-25 15:09:16');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5814, 1, 146, 217, 'RM-N10PRO4G-TL-BLK', 'Redmi N10PRO4G / N10PRO4G / N11E Pro Touch LCD', 'redmi-n10pro4g-n10pro4g-n11e-pro-touch-lcd-7e26j', '<p><strong>N10PRO4G / Redmi N10PRO4G/N11E Pro Touch LCD</strong></p><p>N10PRO4G / Redmi N10PRO4G/N11E Pro Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-N10PRO4G-TL-BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi N10PRO4G / Redmi N10PRO4G/N11E Pro Touch LCD — Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '47000.00', '42300.00', NULL, NULL, '47000.00', 'in_stock', 'products/2CDohhfgYOZ9AD8s9HXc24i9MhQiStq5fP0UkjKX.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-16 15:00:01');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (5815, 1, 146, 217, 'RM-N10PRO5G-TL-ORG -BLK', 'Redmi N10PRO5G Touch LCD', 'redmi-n10pro5g-touch-lcd-uccrk', '<p><strong>N10PRO5G Touch LCD</strong></p><p>N10PRO5G Touch LCD သည် <strong>Redmi</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> RM-N10PRO5G-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Redmi</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Redmi N10PRO5G Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '125000.00', '112500.00', NULL, NULL, '42000.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:09', '2026-08-13 14:21:09');
