INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (6111, 1, 146, 206, 'VV-V9-TL-ORG -BLK', 'Vivo V9 / Y85A Touch LCD', 'vivo-v9-y85a-touch-lcd-b154j', '<p><strong>V9 / Vivo Y85A Touch LCD</strong></p><p>V9 / Vivo Y85A Touch LCD သည် <strong>Vivo</strong> အမှတ်တံဆိပ် Original Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော အရောင်နှင့် ချောမွေ့မြန်ဆန်သော Touch အာရုံခံမှုကို ပြန်လည်ရရှိစေပါသည်။ ဖုန်း၏ မျက်နှာပြင် ပြဿနာကို ဖြေရှင်းရာတွင် အကောင်းဆုံး ရွေးချယ်မှုဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> VV-V9-TL-ORG -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Vivo</li><li><strong>အမျိုးအစား (Category):</strong> Original Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> Original / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Vivo V9 / Vivo Y85A Touch LCD — Original Touch LCD ကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် အသေးစိတ်စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '40000.00', '36000.00', NULL, NULL, '39000.00', 'in_stock', 'products/ksE4cSeN4mBvJwrp4ZCT3XGYirFC6KjRswRHKUb5.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:10', '2026-08-13 18:48:59');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (6112, 1, 150, 206, 'VV-VS1-CV', 'Vivo VS1 Cover', 'vivo-vs1-cover-qlzrt', '<p><strong>VS1 Phone Case</strong></p><p>VS1 Phone Case သည် <strong>Vivo</strong> အမှတ်တံဆိပ် Phone Case အမျိုးအစား (Phone Accessories) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>ဖုန်းကို ထိခိုက်ပျက်စီးမှုနှင့် ခြစ်ရာများမှ ကာကွယ်ပေးနိုင်သော အရည်အသွေးကောင်း ဖုန်းကာဗာဖြစ်ပါသည်။ လက်ကိုင်အနေအထား သက်တောင့်သက်သာရှိပြီး စတိုင်ကျသော အသွင်အပြင်ကိုလည်း ပေးစွမ်းပါသည်။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> VV-VS1-CV</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Vivo</li><li><strong>အမျိုးအစား (Category):</strong> Phone Case</li><li><strong>Parent Category:</strong> Phone Accessories</li><li><strong>စတော့ (Stock):</strong> ယာယီစတော့မရှိ (Out of Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Vivo VS1 Phone Case — Phone Case အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '7000.00', '6500.00', NULL, NULL, '6000.00', 'out_of_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:10', '2026-08-17 09:31:45');
