INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (6135, 1, 146, 206, 'VV-Y19-TL-MA -BLK', 'Vivo Y19 / Y5S Touch LCD (MA / Black)', 'vivo-y19-y5s-touch-lcd-ma-black-vl4ue', '<p><strong>Y19 / Vivo Y5S Touch LCD</strong></p><p>Y19 / Vivo Y5S Touch LCD သည် <strong>Vivo</strong> အမှတ်တံဆိပ် Touch LCD အမျိုးအစား (Screen &amp; LCD) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>Touch LCD မျက်နှာပြင် အစားထိုး အစိတ်အပိုင်းဖြစ်ပြီး ပြတ်သားသော မျက်နှာပြင်နှင့် ချောမွေ့သော Touch ထိန်းချုပ်မှုကို ပြန်လည်ရရှိစေပါသည်။ ပျက်စီးနေသော မျက်နှာပြင်ကို အသစ်ပြန်လည် အစားထိုးရန် သင့်တော်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): MA / Black။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> VV-Y19-TL-MA -BLK</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Vivo</li><li><strong>အမျိုးအစား (Category):</strong> Touch LCD</li><li><strong>Parent Category:</strong> Screen &amp; LCD</li><li><strong>မျိုးကွဲ (Variant):</strong> MA / Black — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Vivo Y19 / Vivo Y5S Touch LCD (MA / Black) — Touch LCD အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '38000.00', '34200.00', NULL, NULL, '37000.00', 'in_stock', 'products/ndFSAWFiFT2HMpnhiOg1V8i7bOeZDo3NNXrMtoBc.webp', '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:10', '2026-08-13 18:53:00');
INSERT INTO `products` (`id`, `store_id`, `category_id`, `brand_id`, `sku`, `name`, `slug`, `description`, `meta_description`, `retail_price`, `old_price`, `sale_starts_at`, `sale_ends_at`, `wholesale_price`, `stock_status`, `image_path`, `warranty`, `return_policy`, `is_featured`, `created_at`, `updated_at`) VALUES (6136, 1, 132, 206, 'VV-Y20(B05)-BT-ORG', 'Vivo Y20(B05) Battery (Original)', 'vivo-y20b05-battery-original-9zohm', '<p><strong>Y20(B05) Battery</strong></p><p>Y20(B05) Battery သည် <strong>Vivo</strong> အမှတ်တံဆိပ် Original Battery အမျိုးအစား (Battery) ပစ္စည်းတစ်ခုဖြစ်ပါသည်။</p><p>မူရင်း (Original) အရည်အသွေးရှိသော ဘက်ထရီဖြစ်ပြီး ဖုန်း၏ စွမ်းဆောင်ရည်ကို အပြည့်အဝ ပြန်လည်ရရှိစေပါသည်။ ကြာရှည်ခံပြီး လုံခြုံစိတ်ချရသော အသုံးပြုမှုအတွက် သင့်လျော်သော ရွေးချယ်မှုတစ်ခု ဖြစ်ပါသည်။</p><p>ရနိုင်သော အမျိုးအစား (Variant): Original။</p><p>အသေးစိတ် အချက်အလက်များ:</p><ul><li><strong>SKU:</strong> VV-Y20(B05)-BT-ORG</li><li><strong>အမှတ်တံဆိပ် (Brand):</strong> Vivo</li><li><strong>အမျိုးအစား (Category):</strong> Original Battery</li><li><strong>Parent Category:</strong> Battery</li><li><strong>မျိုးကွဲ (Variant):</strong> Original — စတော့ရှိသည် (In Stock)</li><li><strong>စတော့ (Stock):</strong> စတော့ရှိသည် (In Stock)</li><li><strong>အာမခံ (Warranty):</strong> ၁ လ အာမခံ</li></ul><p>ALINN THIT တွင် ယုံကြည်စိတ်ချစွာ ဝယ်ယူနိုင်ပြီး အရည်အသွေးကို အာမခံပါသည်။</p>', 'Vivo Y20(B05) Battery (Original) — Original Battery အမျိုးအစားကို ALINN THIT တွင် ဈေးနှုန်း၊ လက်ကျန်နှင့် ပစ္စည်းအသေးစိတ် စစ်ဆေးပြီး မှာယူနိုင်ပါသည်။', '22000.00', '19800.00', NULL, NULL, '20900.00', 'in_stock', NULL, '1 Month Warranty', 'ပစ္စည်းမှားယွင်းမှု သို့မဟုတ် စက်ရုံထုတ်ချို့ယွင်းမှုရှိပါက ဝယ်ယူပြီး 7 ရက်အတွင်း ဘောင်ချာနှင့်တကွ ပြန်လဲနိုင်ပါသည်။ လူကြောင့်ဖြစ်သောပျက်စီးမှု၊ ရေဝင်မှုနှင့် ပြုတ်ကျမှုများ မပါဝင်ပါ။', 0, '2026-08-13 14:21:10', '2026-08-13 14:21:10');
