INSERT INTO `storefront_settings` (`id`, `store_id`, `store_name`, `tagline`, `logo_path`, `storefront_logo_path`, `admin_logo_path`, `favicon_path`, `address`, `phone`, `opening_hours`, `viber_number`, `telegram_username`, `facebook_url`, `youtube_url`, `tiktok_url`, `map_enabled`, `google_maps_url`, `map_latitude`, `map_longitude`, `map_title`, `map_embed_enabled`, `chat_button_label`, `chat_button_url`, `chat_button_icon`, `chat_button_icon_path`, `chat_channels`, `delivery_info`, `payment_info`, `how_to_intro`, `how_to_steps`, `how_to_videos`, `footer_ad_text`, `default_language`, `created_at`, `updated_at`) VALUES (1, 1, 'AlinnThit', 'Mobile Sale Service', 'store-logos/w1Pc9Sgizae6cUnJgeFeJeq5kTxkpRgK6zPstu5R.png', 'store-logos/EU9aTxNGXzb35lHtLnDzO9r8OAtjnal6Rl8DQWKo.webp', 'admin-logos/0PrE72f6lR6cc9snJTCoVo4ExhtHRPPVsknTZynR.webp', 'favicons/Pw1A8rMQ25p7qnKuDKvvx0ldOSW6EyhGHG9z4vLS.webp', 'No. 478, Khaing Shwe War Street, Nyaung Don, Ayeyarwady Region, Myanmar', '09790444128', '8:00AM to 5:30PM', '09790148299', '@alinnthitmobile', 'https://facebook.com/alinnthit', 'https://youtube.com/@alinnthit', 'https://www.tiktok.com/@alinnthit', 1, 'https://maps.app.goo.gl/ugrW3JVwLzCmjQP89', '17.0462098', '95.6441479', 'AlinnThit Shop', 1, 'ဆက်သွယ်ရန်', 'https://t.me/osgunlocker', NULL, 'chat-icons/2b1Vlq2cZbwABuhNF0Hlm7U0JMJLZwrIRefmaUMp.png', '[{\"icon\":\"\\ud83d\\udcac\",\"icon_path\":\"chat-icons\\/P8UbZSJ7gZTNyR93ylnCldGvem8j7l70iworNvMs.png\",\"label\":\"Viber\",\"href\":\"viber:\\/\\/chat?number=959790148299\"},{\"icon\":\"\\u2708\\ufe0f\",\"icon_path\":\"chat-icons\\/Q5qSApGVTV8ZOYxiX8No9GS1QmHER7ieNvt0ZI11.png\",\"label\":\"Telegram\",\"href\":\"@alinnthitmobile\"},{\"icon\":\"\\ud83d\\udcd8\",\"icon_path\":\"chat-icons\\/Txwis7wROlJRa4pRtZhOlCGDVXoenO3BxREsiJyE.png\",\"label\":\"Facebook\",\"href\":\"https:\\/\\/facebook.com\\/alinnthit\"},{\"icon\":\"\\u25b6\\ufe0f\",\"icon_path\":\"chat-icons\\/mzIiDO2O2wVSCcjDhcLoZ3FT3I4ujPKSZ4GTqq9o.png\",\"label\":\"YouTube\",\"href\":\"https:\\/\\/youtube.com\\/@alinnthit\"},{\"icon\":\"\\ud83d\\udcde\",\"icon_path\":null,\"label\":\"Call Now\",\"href\":\"tel:09254343151\"},{\"icon\":\"\\ud83c\\udfb5\",\"icon_path\":\"chat-icons\\/v0HQ1SQHQJ78ataE3dqfpdSvgE6z0sh60TtLAXCw.png\",\"label\":\"TikTok\",\"href\":\"https:\\/\\/www.tiktok.com\\/@alinnthit\"}]', 'ဆိုင်တွင် လာရောက်ဝယ်ယူနိုင်ပါသည်\r\n🚚 ပို့ဆောင်မှုဝန်ဆောင်မှု\r\nမြန်မာနိုင်ငံအနှံ့သို့ ပို့ဆောင်ပေးပါသည်။\r\nRoyal Express, MGL နှင့် အခြားပစ္စည်းပို့ဆောင်နိုင်သော ဝန်ဆောင်မှုများမှတစ်ဆင့် ပို့ဆောင်ပေးပြီး ကားဂိတ်ရှိသော မြို့များသို့လည်း ပို့ဆောင်နိုင်ပါသည်။\r\nDelivery ခနှင့် ပို့ဆောင်ချိန် သည် မြို့နယ်၊ လမ်းကြောင်းနှင့် ပစ္စည်းအရွယ်အစားအပေါ် မူတည်၍ ကွာခြားနိုင်ပါသည်။\r\nOrder အတည်ပြုပြီးနောက် Viber သို့မဟုတ် Telegram မှတစ်ဆင့် Delivery ခ၊ ခန့်မှန်းရောက်ရှိချိန်နှင့် ပို့ဆောင်မှုအသေးစိတ်ကို အတည်ပြုပေးပါမည်။', '💳 ငွေပေးချေနိုင်သော နည်းလမ်းများ\r\nKPay , WavePay , CB Pay , MMQR , COD\r\n✅ ငွေလွှဲပြီးပါက Payment Screenshot ကို Viber သို့မဟုတ် Telegram မှတစ်ဆင့် ပို့ပေးပါရန် မေတ္တာရပ်ခံအပ်ပါသည်။', '👋 အသုံးပြုနည်း\n\nဒီ Website ကို ပထမဆုံးအသုံးပြုသူများအတွက်လည်း လွယ်ကူစွာ အသုံးပြုနိုင်ရန် ဒီဇိုင်းရေးဆွဲထားပါသည်။\n\nအောက်ပါ အဆင့်များအတိုင်း လုပ်ဆောင်လိုက်ရုံဖြင့် ပစ္စည်းမှာယူနိုင်ပါသည်။\n\n1️⃣ ပစ္စည်းရှာဖွေပါ။\n2️⃣ ဈေးနှုန်းနှင့် အသေးစိတ်အချက်အလက်များကို ကြည့်ရှုပါ။\n3️⃣ လိုချင်သောပစ္စည်းကို Order List ထဲသို့ ထည့်ပါ။\n4️⃣ Order ကို ဆိုင်သို့ ပို့ပါ။\n5️⃣ ဆိုင်ဘက်မှ Order ကို အတည်ပြုပေးပါမည်။\n6️⃣ အတည်ပြုပြီးနောက် ငွေပေးချေ၍ Order ကို အပြီးသတ်နိုင်ပါသည်။\n\n❓ မရှင်းလင်းသောအချက်များရှိပါက Screenshot နှင့်တကွ Viber သို့မဟုတ် Telegram မှတစ်ဆင့် ဆက်သွယ်မေးမြန်းနိုင်ပါသည်။', '[{\"icon\":\"\\ud83d\\udd0e\",\"title\":\"\\ud83d\\udd0d \\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u101b\\u103e\\u102c\\u1016\\u103d\\u1031\\u1014\\u100a\\u103a\\u1038\",\"desc\":\"\\ud83d\\udce6 Products \\u1011\\u1032\\u101e\\u102d\\u102f\\u1037\\u101d\\u1004\\u103a\\u1015\\u103c\\u102e\\u1038 Mobile\\u104a Accessories\\u104a CCTV\\u104a Computer \\u1014\\u103e\\u1004\\u1037\\u103a Fashion Category \\u1019\\u103b\\u102c\\u1038\\u1019\\u103e \\u101c\\u102d\\u102f\\u1021\\u1015\\u103a\\u101e\\u1031\\u102c\\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u1000\\u102d\\u102f \\u101b\\u103e\\u102c\\u1016\\u103d\\u1031\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\\n\\n\\ud83d\\udcf1 \\u1016\\u102f\\u1014\\u103a\\u1038\\u1019\\u103e\\u1014\\u103a (Glass) \\u101b\\u103e\\u102c\\u101c\\u102d\\u102f\\u1015\\u102b\\u1000 Glass Finder \\u1000\\u102d\\u102f \\u1014\\u103e\\u102d\\u1015\\u103a\\u1015\\u103c\\u102e\\u1038 \\u1016\\u102f\\u1014\\u103a\\u1038\\u1019\\u1031\\u102c\\u103a\\u1012\\u101a\\u103a\\u1021\\u1019\\u100a\\u103a (\\u1025\\u1015\\u1019\\u102c \\u2013 iPhone 13 Pro, Redmi Note 12, Samsung A15) \\u1000\\u102d\\u102f \\u101b\\u102d\\u102f\\u1000\\u103a\\u1011\\u100a\\u1037\\u103a\\u104d \\u1021\\u101c\\u103d\\u101a\\u103a\\u1010\\u1000\\u1030 \\u101b\\u103e\\u102c\\u1016\\u103d\\u1031\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\"},{\"icon\":\"\\ud83d\\udc40\",\"title\":\"\\ud83d\\udc40 \\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u1021\\u101e\\u1031\\u1038\\u1005\\u102d\\u1010\\u103a \\u1000\\u103c\\u100a\\u1037\\u103a\\u101b\\u103e\\u102f\\u1014\\u100a\\u103a\\u1038\",\"desc\":\"\\ud83d\\udcf7 \\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u1015\\u102f\\u1036 \\u1014\\u103e\\u1004\\u1037\\u103a \\u1008\\u1031\\u1038\\u1014\\u103e\\u102f\\u1014\\u103a\\u1038 \\u1000\\u102d\\u102f \\u1000\\u103c\\u100a\\u1037\\u103a\\u101b\\u103e\\u102f\\u1015\\u102b\\u104b\\n\\n\\ud83d\\udce6 Stock \\u101b\\u103e\\u102d \\/ \\u1019\\u101b\\u103e\\u102d \\u1014\\u103e\\u1004\\u1037\\u103a Variant (\\u1021\\u101b\\u1031\\u102c\\u1004\\u103a\\u104a Size\\u104a Storage \\u1005\\u101e\\u100a\\u103a) \\u1000\\u102d\\u102f \\u101b\\u103d\\u1031\\u1038\\u1001\\u103b\\u101a\\u103a\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\\n\\n\\ud83d\\udcbc Wholesale Account \\u1016\\u103c\\u1004\\u1037\\u103a Login \\u101d\\u1004\\u103a\\u1011\\u102c\\u1038\\u1015\\u102b\\u1000 Wholesale \\u1008\\u1031\\u1038\\u1014\\u103e\\u102f\\u1014\\u103a\\u1038 \\u1000\\u102d\\u102f\\u101c\\u100a\\u103a\\u1038 \\u1000\\u103c\\u100a\\u1037\\u103a\\u101b\\u103e\\u102f\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\"},{\"icon\":\"\\ud83d\\uded2\",\"title\":\"\\ud83d\\uded2 Order List \\u1011\\u1032\\u101e\\u102d\\u102f\\u1037 \\u1011\\u100a\\u1037\\u103a\\u1014\\u100a\\u103a\\u1038\",\"desc\":\"\\u2795 \\u101c\\u102d\\u102f\\u1001\\u103b\\u1004\\u103a\\u101e\\u1031\\u102c\\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u1000\\u102d\\u102f Add to Order List \\u1000\\u102d\\u102f\\u1014\\u103e\\u102d\\u1015\\u103a\\u104d \\u1011\\u100a\\u1037\\u103a\\u1015\\u102b\\u104b\\n\\n\\ud83d\\udd22 \\u1010\\u1005\\u103a\\u1001\\u102f\\u1011\\u1000\\u103a\\u1015\\u102d\\u102f\\u1019\\u103e\\u102c\\u101a\\u1030\\u101c\\u102d\\u102f\\u1015\\u102b\\u1000 Qty \\u1000\\u102d\\u102f \\u101c\\u102d\\u102f\\u1021\\u1015\\u103a\\u101e\\u101c\\u102d\\u102f \\u1015\\u103c\\u1004\\u103a\\u1006\\u1004\\u103a\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\\n\\n\\ud83d\\udecd\\ufe0f \\u1015\\u103c\\u102e\\u1038\\u1015\\u102b\\u1000 Cart \\u101e\\u102d\\u102f\\u1037\\u1019\\u101f\\u102f\\u1010\\u103a Order Builder \\u1011\\u1032\\u1010\\u103d\\u1004\\u103a Order \\u1005\\u102c\\u101b\\u1004\\u103a\\u1038\\u1000\\u102d\\u102f \\u1015\\u103c\\u1014\\u103a\\u101c\\u100a\\u103a\\u1005\\u1005\\u103a\\u1006\\u1031\\u1038\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\"},{\"icon\":\"\\ud83d\\udcac\",\"title\":\"\\ud83d\\udce4 Order \\u1015\\u102d\\u102f\\u1037\\u1014\\u100a\\u103a\\u1038\",\"desc\":\"\\ud83d\\udcdd \\u1014\\u102c\\u1019\\u100a\\u103a\\u104a \\u1016\\u102f\\u1014\\u103a\\u1038\\u1014\\u1036\\u1015\\u102b\\u1010\\u103a \\u1014\\u103e\\u1004\\u1037\\u103a \\u1015\\u102d\\u102f\\u1037\\u1006\\u1031\\u102c\\u1004\\u103a\\u1019\\u100a\\u1037\\u103a\\u101c\\u102d\\u1015\\u103a\\u1005\\u102c \\u1000\\u102d\\u102f \\u1016\\u103c\\u100a\\u1037\\u103a\\u101e\\u103d\\u1004\\u103a\\u1038\\u1015\\u102b\\u104b\\n\\n\\ud83d\\udcf2 Order \\u1000\\u102d\\u102f Viber \\u101e\\u102d\\u102f\\u1037\\u1019\\u101f\\u102f\\u1010\\u103a Telegram \\u1019\\u103e\\u1010\\u1005\\u103a\\u1006\\u1004\\u1037\\u103a \\u1006\\u102d\\u102f\\u1004\\u103a\\u101e\\u102d\\u102f\\u1037 \\u1015\\u1031\\u1038\\u1015\\u102d\\u102f\\u1037\\u1015\\u102b\\u104b\\n\\n\\u2705 \\u1006\\u102d\\u102f\\u1004\\u103a\\u1018\\u1000\\u103a\\u1019\\u103e Stock \\u101b\\u103e\\u102d\\/\\u1019\\u101b\\u103e\\u102d\\u104a \\u1008\\u1031\\u1038\\u1014\\u103e\\u102f\\u1014\\u103a\\u1038 \\u1014\\u103e\\u1004\\u1037\\u103a Delivery \\u1001 \\u1000\\u102d\\u102f \\u1015\\u103c\\u1014\\u103a\\u101c\\u100a\\u103a\\u1021\\u1010\\u100a\\u103a\\u1015\\u103c\\u102f\\u1015\\u1031\\u1038\\u1015\\u102b\\u1019\\u100a\\u103a\\u104b\"},{\"icon\":\"\\ud83d\\udce6\",\"title\":\"\\ud83d\\udcb3 \\u1004\\u103d\\u1031\\u1015\\u1031\\u1038\\u1001\\u103b\\u1031\\u1001\\u103c\\u1004\\u103a\\u1038 & \\ud83d\\udce6 \\u1015\\u1005\\u1039\\u1005\\u100a\\u103a\\u1038\\u101c\\u1000\\u103a\\u1001\\u1036\\u1001\\u103c\\u1004\\u103a\\u1038\",\"desc\":\"\\ud83d\\udcb0 KBZ Pay\\u104a Wave Pay\\u104a Bank Transfer \\u101e\\u102d\\u102f\\u1037\\u1019\\u101f\\u102f\\u1010\\u103a Cash on Delivery (COD) \\u1016\\u103c\\u1004\\u1037\\u103a \\u1021\\u1006\\u1004\\u103a\\u1015\\u103c\\u1031\\u101e\\u101c\\u102d\\u102f \\u1004\\u103d\\u1031\\u1015\\u1031\\u1038\\u1001\\u103b\\u1031\\u1014\\u102d\\u102f\\u1004\\u103a\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\\n\\n\\ud83c\\udfea \\u1006\\u102d\\u102f\\u1004\\u103a\\u1010\\u103d\\u1004\\u103a \\u101c\\u102c\\u101b\\u1031\\u102c\\u1000\\u103a\\u1011\\u102f\\u1010\\u103a\\u101a\\u1030\\u1014\\u102d\\u102f\\u1004\\u103a\\u101e\\u101c\\u102d\\u102f \\ud83d\\ude9a Delivery Service \\u1016\\u103c\\u1004\\u1037\\u103a\\u101c\\u100a\\u103a\\u1038 \\u1019\\u103c\\u1014\\u103a\\u1019\\u102c\\u1014\\u102d\\u102f\\u1004\\u103a\\u1004\\u1036\\u1021\\u1014\\u103e\\u1036\\u1037\\u101e\\u102d\\u102f\\u1037 \\u1015\\u102d\\u102f\\u1037\\u1006\\u1031\\u102c\\u1004\\u103a\\u1015\\u1031\\u1038\\u1015\\u102b\\u101e\\u100a\\u103a\\u104b\"}]', '[]', '🛍️ ရောင်းချပေးနေသော ပစ္စည်းများ\r\n\r\n📱 Mobile\r\n🎧 Accessories\r\n📷 CCTV\r\n💻 Computer\r\n👕 Fashion\r\n🕶️ Glass\r\n\r\nလက်လီ (Retail) နှင့် လက်ကား (Wholesale) အော်ဒါများကို ဝန်ဆောင်မှုပေးလျက်ရှိပါသည်။', 'my', '2026-07-29 02:33:32', '2026-08-10 16:53:27');
